package codeshape

import (
	"bytes"
	"testing"
)

func TestRender(t *testing.T) {
	allow := Allowlist{
		Files: map[string]Entry{
			"z.go": {Value: 501, Reason: "split by concern"},
			"a.go": {Value: 502, Reason: "generated by codegen"},
		},
		Dirs:      map[string]Entry{"pkg": {Value: 11, Reason: "split package tests"}},
		Functions: map[string]map[string][]FunctionEntry{},
		Present:   false,
	}
	first := Render(allow)
	second := Render(allow)
	if !bytes.Equal(first, second) {
		t.Fatalf("Render changed between calls: %q != %q", first, second)
	}
	want := []byte(
		"files: {\n\t\"a.go\": {value: 502, reason: \"generated by codegen\"},\n" +
			"\t\"z.go\": {value: 501, reason: \"split by concern\"},\n}\n" +
			"dirs: {\n\t\"pkg\": {value: 11, reason: \"split package tests\"},\n}\n",
	)
	if !bytes.Equal(first, want) {
		t.Fatalf("Render = %q, want %q", first, want)
	}
}

func TestRenderFunctionEntriesSorted(t *testing.T) {
	allow := Allowlist{
		Functions: map[string]map[string][]FunctionEntry{
			"go-lines": {"a.go": {
				{ID: "z", Value: 62, Reason: "split by concern"},
				{ID: "a", Value: 61, Reason: "split by concern"},
			}},
		},
		Files:   map[string]Entry{},
		Dirs:    map[string]Entry{},
		Present: false,
	}
	output := Render(allow)
	if bytes.Index(output, []byte(`id: "a"`)) >= bytes.Index(output, []byte(`id: "z"`)) {
		t.Fatalf("function entries not sorted: %s", output)
	}
	if allow.Functions["go-lines"]["a.go"][0].ID != "z" {
		t.Fatal("Render mutated input")
	}
}
